func InitiateWaiver(ctx context.Context, caps capabilities.InitiateWaiverCapabilities, input capabilities.InitiateWaiverInput) (capabilities.InitiateWaiverOutput, error) {
	if caps.Execution == nil || caps.ServiceRequest == nil || caps.WarrantyWaiver == nil || caps.WarrantyApproval == nil || caps.Notifications == nil {
		return capabilities.InitiateWaiverOutput{}, reject("field_service.capability_unavailable")
	}
	if strings.TrimSpace(input.IdempotencyKey) == "" {
		return capabilities.InitiateWaiverOutput{}, reject("field_service.invalid_idempotency_key")
	}
	requestedCents, err := parseMoneyCents(string(input.RequestedAmount))
	if err != nil || requestedCents <= 0 {
		return capabilities.InitiateWaiverOutput{}, reject("field_service.invalid_waiver_amount")
	}
	principal := caps.Execution.Principal()
	record, err := caps.ServiceRequest.GetForUpdate(ctx, caps.Execution.TargetID())
	if err != nil {
		return capabilities.InitiateWaiverOutput{}, err
	}
	if record.Status != statusCompleted {
		return capabilities.InitiateWaiverOutput{}, reject("field_service.waiver_requires_completed_request")
	}
	if err := requireAssigned(record, principal.UserID); err != nil {
		return capabilities.InitiateWaiverOutput{}, err
	}
	quotedCents, err := parseMoneyCents(string(record.QuotedAmount))
	if err != nil || requestedCents > quotedCents {
		return capabilities.InitiateWaiverOutput{}, reject("field_service.invalid_waiver_amount")
	}
	ref := schema.NewWarrantyWaiverServiceRequestIDReference(record.ID)
	exists, err := caps.WarrantyWaiver.Exists(ctx, data.NewWarrantyWaiverQuery().WhereServiceRequestIDEqual(ref).Page(1, 1))
	if err != nil {
		return capabilities.InitiateWaiverOutput{}, err
	}
	if exists {
		return capabilities.InitiateWaiverOutput{}, reject("field_service.waiver_already_exists")
	}
	waiverStatus := schema.WarrantyWaiverStatus("pending")
	if requestedCents < 50000 {
		waiverStatus = schema.WarrantyWaiverStatus("applied")
	}
	waiver, err := caps.WarrantyWaiver.Create(ctx, schema.CreateWarrantyWaiver{
		ServiceRequestID:     ref,
		RequestedBy:          principal.UserID,
		RequestedAmount:      input.RequestedAmount,
		QuotedAmountSnapshot: schema.WarrantyWaiverQuotedAmountSnapshot(record.QuotedAmount),
		ThresholdSnapshot:    schema.WarrantyWaiverThresholdSnapshot("500.00"),
		Status:               waiverStatus,
		IdempotencyKey:       input.IdempotencyKey,
	})
	if err != nil {
		return capabilities.InitiateWaiverOutput{}, err
	}
	if waiverStatus == schema.WarrantyWaiverStatus("pending") {
		_, err = caps.WarrantyApproval.Create(ctx, schema.CreateWarrantyApproval{
			WaiverID:         schema.NewWarrantyApprovalWaiverIDReference(waiver.ID),
			ServiceRequestID: schema.NewWarrantyApprovalServiceRequestIDReference(record.ID),
			RequestedBy:      principal.UserID,
			Status:           schema.WarrantyApprovalStatus("pending"),
		})
		if err != nil {
			return capabilities.InitiateWaiverOutput{}, err
		}
	} else {
		final := schema.ServiceRequestFinalAmount(formatMoneyCents(quotedCents - requestedCents))
		updated, err := caps.ServiceRequest.ConditionalUpdate(ctx, data.NewServiceRequestUpdate(record.ID).
